export function hash2(x,y,SEED){let h=(x*374761393+y*668265263+SEED*1442695040888963407)|0;h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296}
export function hash3(x,y,z,SEED){let h=(x*374761393+y*668265263+z*1442695040888963407+SEED*998244353)|0;h=Math.imul(h^(h>>>13),1274126177);return((h^(h>>>16))>>>0)/4294967296}
export function smoothstep(t){return t*t*(3-2*t)}
export function noise2D(x,y,SEED){const xi=Math.floor(x),yi=Math.floor(y),xf=x-xi,yf=y-yi;const a=hash2(xi,yi,SEED),b=hash2(xi+1,yi,SEED),c=hash2(xi,yi+1,SEED),d=hash2(xi+1,yi+1,SEED);const u=smoothstep(xf),v=smoothstep(yf);return a*(1-u)*(1-v)+b*u*(1-v)+c*(1-u)*v+d*u*v}
export function fbm(x,y,SEED,oct=4){let value=0,amp=1,freq=1,max=0;for(let i=0;i<oct;i++){value+=noise2D(x*freq,y*freq,SEED)*amp;max+=amp;amp*=.5;freq*=2}return value/max}
export function noise3D(x,y,z,SEED){const xi=Math.floor(x),yi=Math.floor(y),zi=Math.floor(z);const xf=x-xi,yf=y-yi,zf=z-zi;const u=smoothstep(xf),v=smoothstep(yf),w=smoothstep(zf);const c000=hash3(xi,yi,zi,SEED),c100=hash3(xi+1,yi,zi,SEED),c010=hash3(xi,yi+1,zi,SEED),c110=hash3(xi+1,yi+1,zi,SEED),c001=hash3(xi,yi,zi+1,SEED),c101=hash3(xi+1,yi,zi+1,SEED),c011=hash3(xi,yi+1,zi+1,SEED),c111=hash3(xi+1,yi+1,zi+1,SEED);const x00=c000*(1-u)+c100*u,x10=c010*(1-u)+c110*u,x01=c001*(1-u)+c101*u,x11=c011*(1-u)+c111*u;const y0=x00*(1-v)+x10*v,y1=x01*(1-v)+x11*v;return y0*(1-w)+y1*w}
export function fbm3D(x,y,z,SEED,oct=3){let value=0,amp=1,freq=1,max=0;for(let i=0;i<oct;i++){value+=noise3D(x*freq,y*freq,z*freq,SEED)*amp;max+=amp;amp*=.5;freq*=2}return value/max}